// Live GitHub telemetry card. Regenerated by .github/workflows/telemetry.yml.
// Usage: GITHUB_TOKEN=... USERNAME=... [ACCENT=#hex] [OWN_ORGS=a,b] node telemetry.mjs <out.svg>
import { writeFileSync } from "node:fs";

const token = process.env.GITHUB_TOKEN;
const login = process.env.USERNAME;
const out = process.argv[2] ?? "assets/telemetry.svg";
const ownOrgs = new Set([login, ...(process.env.OWN_ORGS ?? "").split(",").filter(Boolean)].map((s) => s.toLowerCase()));

const C = {
  bg: "#05070e", line: "#1a2033", text: "#e6e9f5", dim: "#7d849b", faint: "#4a5068",
  accent: process.env.ACCENT ?? "#5e6ad2", accent2: process.env.ACCENT2 ?? "#00e5ff",
  merged: "#a371f7", open: "#3fb950", closed: "#f85149",
};
const MONO = `'JetBrains Mono','SF Mono','Cascadia Code',Consolas,'Liberation Mono',monospace`;
const SANS = `'Inter','Segoe UI',-apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const clip = (s, n) => (s.length > n ? s.slice(0, n - 1) + "…" : s);
const fmt = (n) => (n >= 10000 ? (n / 1000).toFixed(1) + "k" : n.toLocaleString("en-US"));

const query = `query($login: String!) {
  user(login: $login) {
    followers { totalCount }
    contributionsCollection {
      totalCommitContributions
      totalPullRequestReviewContributions
      contributionCalendar { totalContributions weeks { contributionDays { date contributionCount } } }
    }
    pullRequests(first: 100, orderBy: { field: CREATED_AT, direction: DESC }) {
      totalCount
      nodes { title number state createdAt repository { nameWithOwner owner { login } } }
    }
    repositories(first: 100, ownerAffiliations: OWNER, privacy: PUBLIC, isFork: false) {
      totalCount
      nodes { stargazerCount languages(first: 10) { edges { size node { name color } } } }
    }
  }
}`;

const res = await fetch("https://api.github.com/graphql", {
  method: "POST",
  headers: { authorization: `bearer ${token}`, "content-type": "application/json", "user-agent": "profile-telemetry" },
  body: JSON.stringify({ query, variables: { login } }),
});
const json = await res.json();
if (!res.ok || json.errors) throw new Error(JSON.stringify(json.errors ?? json));
const u = json.data.user;
const cc = u.contributionsCollection;

// ── metrics ──
const days = cc.contributionCalendar.weeks.flatMap((w) => w.contributionDays);
const today = new Date().toISOString().slice(0, 10);
const past = days.filter((d) => d.date <= today);
let streak = 0;
for (let i = past.length - 1; i >= 0; i--) {
  if (past[i].contributionCount > 0) streak++;
  else if (i === past.length - 1) continue; // today may not have activity yet
  else break;
}
let best = 0, run = 0;
for (const d of past) { run = d.contributionCount > 0 ? run + 1 : 0; best = Math.max(best, run); }

const prs = u.pullRequests.nodes;
const upstream = prs.filter((p) => !ownOrgs.has(p.repository.owner.login.toLowerCase()));
const upstreamMerged = upstream.filter((p) => p.state === "MERGED").length;
const upstreamRepos = new Set(upstream.map((p) => p.repository.nameWithOwner)).size;
const stars = u.repositories.nodes.reduce((a, r) => a + r.stargazerCount, 0);

const langs = new Map();
for (const r of u.repositories.nodes)
  for (const e of r.languages.edges) {
    const cur = langs.get(e.node.name) ?? { size: 0, color: e.node.color ?? C.dim };
    cur.size += e.size;
    langs.set(e.node.name, cur);
  }
const langTotal = [...langs.values()].reduce((a, l) => a + l.size, 0) || 1;
const topLangs = [...langs.entries()].filter(([, l]) => l.size / langTotal >= 0.005).sort((a, b) => b[1].size - a[1].size).slice(0, 6);

const tiles = [
  [fmt(cc.contributionCalendar.totalContributions), "contributions · 12mo"],
  [`${streak}d`, `current streak · best ${best}d`],
  [fmt(cc.totalCommitContributions), "commits · 12mo"],
  [fmt(upstream.length), `upstream PRs · ${upstreamRepos} projects`],
  [fmt(upstreamMerged), "upstream merged"],
  [fmt(stars), `stars · ${u.repositories.totalCount} repos`],
];

// ── layout ──
const W = 1200, H = 520;
let body = "";

// stat tiles
const tw = (W - 60 - 5 * 12) / 6;
tiles.forEach(([v, label], i) => {
  const x = 30 + i * (tw + 12);
  body += `<g class="f" style="animation-delay:${(0.15 + i * 0.08).toFixed(2)}s" transform="translate(${x.toFixed(1)},64)">
    <rect width="${tw.toFixed(1)}" height="86" rx="10" fill="#0c101d" stroke="${C.line}"/>
    <rect width="3" height="34" y="14" rx="1.5" fill="${i % 2 ? C.accent2 : C.accent}"/>
    <text x="16" y="44" font-family="${SANS}" font-size="30" font-weight="700" letter-spacing="-.8" fill="${C.text}">${esc(v)}</text>
    <text x="16" y="70" font-family="${MONO}" font-size="10.5" fill="${C.dim}">${esc(label)}</text>
  </g>`;
});

// language bar
let lx = 30;
const barW = W - 60;
body += `<text x="30" y="186" font-family="${MONO}" font-size="11" letter-spacing="1.5" fill="${C.faint}">LANGUAGE MIX · PUBLIC REPOS</text>`;
body += `<clipPath id="lb"><rect x="30" y="196" width="${barW}" height="10" rx="5"/></clipPath><g clip-path="url(#lb)" class="grow">`;
for (const [, l] of topLangs) { const w = (l.size / langTotal) * barW; body += `<rect x="${lx.toFixed(1)}" y="196" width="${(w + 0.5).toFixed(1)}" height="10" fill="${l.color}"/>`; lx += w; }
body += `<rect x="${lx.toFixed(1)}" y="196" width="${Math.max(0, 30 + barW - lx).toFixed(1)}" height="10" fill="${C.line}"/></g>`;
let legX = 30;
for (const [name, l] of topLangs) {
  const label = `${name} ${((l.size / langTotal) * 100).toFixed(1)}%`;
  body += `<circle cx="${legX + 5}" cy="226" r="4.5" fill="${l.color}"/><text x="${legX + 15}" y="230" font-family="${MONO}" font-size="11.5" fill="${C.dim}">${esc(label)}</text>`;
  legX += label.length * 7.1 + 34;
}

// 90-day activity area chart
const series = past.slice(-90);
const cx0 = 30, cy0 = 270, cw = 700, ch = 210;
const max = Math.max(1, ...series.map((d) => d.contributionCount));
// sqrt scale so one burst day doesn't flatten the rest of the quarter
const pts = series.map((d, i) => [cx0 + (i / (series.length - 1)) * cw, cy0 + ch - 10 - Math.sqrt(d.contributionCount / max) * (ch - 50)]);
const line = pts.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
const area = `${line} L${cx0 + cw} ${cy0 + ch - 10} L${cx0} ${cy0 + ch - 10} Z`;
const total90 = series.reduce((a, d) => a + d.contributionCount, 0);
body += `<text x="${cx0}" y="${cy0 - 4}" font-family="${MONO}" font-size="11" letter-spacing="1.5" fill="${C.faint}">ACTIVITY · LAST 90 DAYS</text>
  <text x="${cx0 + cw}" y="${cy0 - 4}" text-anchor="end" font-family="${MONO}" font-size="11" fill="${C.dim}">${fmt(total90)} contributions · peak ${max}/day · √ scale</text>
  <rect x="${cx0}" y="${cy0 + 6}" width="${cw}" height="${ch - 10}" rx="10" fill="#0c101d" stroke="${C.line}"/>
  ${[0.25, 0.5, 0.75].map((f) => `<line x1="${cx0}" x2="${cx0 + cw}" y1="${(cy0 + 40 + f * (ch - 50)).toFixed(1)}" y2="${(cy0 + 40 + f * (ch - 50)).toFixed(1)}" stroke="#ffffff" stroke-opacity=".04"/>`).join("")}
  <path d="${area}" fill="url(#ar)" class="f" style="animation-delay:.9s"/>
  <path d="${line}" fill="none" stroke="url(#ln)" stroke-width="2.2" stroke-linejoin="round" class="draw"/>
  <circle cx="${pts.at(-1)[0].toFixed(1)}" cy="${pts.at(-1)[1].toFixed(1)}" r="4" fill="${C.accent2}"/>
  <circle cx="${pts.at(-1)[0].toFixed(1)}" cy="${pts.at(-1)[1].toFixed(1)}" r="4" fill="none" stroke="${C.accent2}" class="pulse"/>`;

// upstream feed
const fx = 760, fw = W - 30 - fx;
body += `<text x="${fx}" y="${cy0 - 4}" font-family="${MONO}" font-size="11" letter-spacing="1.5" fill="${C.faint}">LATEST PULL REQUESTS</text>
  <rect x="${fx}" y="${cy0 + 6}" width="${fw}" height="${ch - 10}" rx="10" fill="#0c101d" stroke="${C.line}"/>`;
const feed = (upstream.length ? upstream : prs).slice(0, 5);
feed.forEach((p, i) => {
  const y = cy0 + 36 + i * 37;
  const col = { MERGED: C.merged, OPEN: C.open, CLOSED: C.closed }[p.state];
  body += `<g class="f" style="animation-delay:${(1 + i * 0.12).toFixed(2)}s">
    <circle cx="${fx + 20}" cy="${y - 4}" r="4.5" fill="${col}"/>
    <text x="${fx + 34}" y="${y}" font-family="${MONO}" font-size="11.5" fill="${C.text}">${esc(clip(`${p.repository.nameWithOwner}#${p.number}`, 40))}</text>
    <text x="${fx + fw - 16}" y="${y}" text-anchor="end" font-family="${MONO}" font-size="10.5" fill="${col}">${p.state.toLowerCase()}</text>
    <text x="${fx + 34}" y="${y + 16}" font-family="${SANS}" font-size="12" fill="${C.dim}">${esc(clip(p.title, 52))}</text>
  </g>`;
});
if (!feed.length) body += `<text x="${fx + 20}" y="${cy0 + 40}" font-family="${MONO}" font-size="12" fill="${C.dim}">no pull requests yet</text>`;

const stamp = new Date().toISOString().replace("T", " ").slice(0, 16) + " UTC";
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Live GitHub telemetry for ${esc(login)}">
  <title>Live GitHub telemetry for ${esc(login)}</title>
  <defs>
    <linearGradient id="bd" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${C.accent}" stop-opacity=".9"/><stop offset=".5" stop-color="${C.line}" stop-opacity=".6"/><stop offset="1" stop-color="${C.accent2}" stop-opacity=".8"/></linearGradient>
    <linearGradient id="gl" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#10152a"/><stop offset="1" stop-color="${C.bg}"/></linearGradient>
    <radialGradient id="orb" cx=".15" cy="0" r=".8"><stop offset="0" stop-color="${C.accent}" stop-opacity=".22"/><stop offset="1" stop-color="${C.accent}" stop-opacity="0"/></radialGradient>
    <linearGradient id="ar" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${C.accent2}" stop-opacity=".35"/><stop offset="1" stop-color="${C.accent}" stop-opacity="0"/></linearGradient>
    <linearGradient id="ln" x1="0" x2="1"><stop offset="0" stop-color="${C.accent}"/><stop offset="1" stop-color="${C.accent2}"/></linearGradient>
    <pattern id="gr" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#ffffff" stroke-opacity=".035"/></pattern>
  </defs>
  <style>
    .f { opacity: 0; animation: in .5s ease-out forwards; }
    @keyframes in { from { opacity: 0; transform: translateY(6px) } to { opacity: 1; transform: none } }
    .draw { stroke-dasharray: 3000; stroke-dashoffset: 3000; animation: draw 2.2s .5s ease-out forwards; }
    @keyframes draw { to { stroke-dashoffset: 0 } }
    .grow { transform-box: fill-box; transform-origin: left; animation: grow 1.2s .4s cubic-bezier(.2,.8,.2,1) both; }
    @keyframes grow { from { transform: scaleX(0) } to { transform: scaleX(1) } }
    .pulse { transform-box: fill-box; transform-origin: center; animation: pulse 2.4s ease-out infinite; }
    @keyframes pulse { 0% { transform: scale(1); opacity: .9 } 100% { transform: scale(3.2); opacity: 0 } }
    @media (prefers-reduced-motion: reduce) { * { animation: none !important; opacity: 1 !important; stroke-dashoffset: 0 !important } }
  </style>
  <rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="14" fill="url(#gl)"/>
  <rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="14" fill="url(#gr)"/>
  <rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="14" fill="url(#orb)"/>
  <rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="14" fill="none" stroke="url(#bd)"/>
  <circle cx="36" cy="35" r="4" fill="${C.open}"/><circle cx="36" cy="35" r="4" fill="none" stroke="${C.open}" class="pulse"/>
  <text x="50" y="39" font-family="${MONO}" font-size="11.5" letter-spacing="1.5" fill="${C.accent2}">TELEMETRY · LIVE · @${esc(login.toUpperCase())}</text>
  <text x="${W - 30}" y="39" text-anchor="end" font-family="${MONO}" font-size="11" fill="${C.faint}">synced ${stamp} · github graphql</text>
  ${body}
</svg>
`;
writeFileSync(out, svg);
console.log(`telemetry → ${out}: ${tiles.map((t) => t[0]).join(" / ")}`);
